import { ipcMain, shell } from 'electron';
import { ScannerService } from './services/scanner';
import { updaterService } from './services/updater';
import { storage } from './services/storage';
import { settingsStore } from './services/settings';
import { aiService } from './services/aiService';
import { dependencyService, DEPENDENCIES } from './services/dependencyManager';
import { toolManager } from './services/toolManager';

export const scannerService = new ScannerService();

// Unified Tool Engine Handlers
ipcMain.handle('tools:get-health', async () => {
  return await toolManager.getHealthMatrix();
});

ipcMain.handle('tools:update-single', async (event, toolName: string) => {
  return await toolManager.updateTool(toolName, event.sender);
});

ipcMain.handle('tools:update-all', async (event) => {
  return await toolManager.updateAll(event.sender);
});

// Legacy Tools Update
ipcMain.handle('tools:update', async (event) => {
  return await toolManager.updateAll(event.sender);
});

ipcMain.handle('dependency:check', async () => {
  return DEPENDENCIES.map(tool => ({
    name: tool.name,
    isInstalled: dependencyService.isInstalled(tool.name),
    requiresManual: !!tool.requiresManual
  }));
});

ipcMain.handle('dependency:installAll', async (event) => {
  await dependencyService.checkAndInstallAll(event.sender);
  return { success: true };
});

ipcMain.handle('scan:start', async (event, targetUrl, config) => {
  return await scannerService.startScan(event.sender, targetUrl, config);
});

ipcMain.handle('scan:stop', async (event, scanId) => {
  return await scannerService.stopScan(scanId);
});

// Storage and History
ipcMain.handle('storage:getHistory', async () => {
  return storage.getHistory();
});

ipcMain.handle('storage:getFindingsPaginated', async (event, scanId, options) => {
  const { dbService } = await import('./services/database');
  return dbService.getFindingsPaginated(scanId, options);
});

ipcMain.handle('storage:openFolder', async (event, scanId) => {
  storage.openFolder(scanId);
});

// Report Exports
ipcMain.handle('report:export', async (event, scanId: string, format: 'html' | 'md' | 'json') => {
  const { reportService } = await import('./services/reportService');
  let filePath = '';
  if (format === 'html') {
    filePath = await reportService.generateHtmlReport(scanId);
  } else if (format === 'md') {
    filePath = await reportService.generateMarkdownReport(scanId);
  } else {
    filePath = await reportService.exportJsonReport(scanId);
  }
  return { success: true, filePath };
});

ipcMain.handle('report:getStats', async (event, scanId: string) => {
  const { reportService } = await import('./services/reportService');
  const data = await reportService.compileReportData(scanId);
  return {
    ...data,
    metrics: reportService.calculateStats(data.findings)
  };
});

// Settings — persisted to disk
ipcMain.handle('settings:get', async () => {
  return settingsStore.get();
});

ipcMain.handle('settings:save', async (event, settings) => {
  return settingsStore.save(settings);
});

// AI Service
ipcMain.handle('ai:analyzeLogs', async (event, logs, prompt) => {
  return await aiService.analyzeLogs(event.sender, logs, prompt);
});

// Shell
ipcMain.handle('shell:openExternal', async (event, url) => {
  await shell.openExternal(url);
});

import fs, { promises as fsPromises } from 'fs';
import path from 'path';
import os from 'os';
import axios from 'axios';
import extract from 'extract-zip';
import { exec, spawn } from 'child_process';
import { logger } from './logger';

export interface ToolDependency {
  name: string;
  repo: string; // e.g., "projectdiscovery/nuclei"
  exeName: string; // e.g., "nuclei.exe"
  assetPrefix: string; // e.g., "nuclei_"
  assetSuffix: string; // e.g., "_windows_amd64.zip"
  requiresManual?: boolean;
  pipPackage?: string;
  gitRepo?: string;
}

export const DEPENDENCIES: ToolDependency[] = [
  { name: 'nuclei', repo: 'projectdiscovery/nuclei', exeName: 'nuclei.exe', assetPrefix: 'nuclei_', assetSuffix: '_windows_amd64.zip' },
  { name: 'subfinder', repo: 'projectdiscovery/subfinder', exeName: 'subfinder.exe', assetPrefix: 'subfinder_', assetSuffix: '_windows_amd64.zip' },
  { name: 'httpx', repo: 'projectdiscovery/httpx', exeName: 'httpx.exe', assetPrefix: 'httpx_', assetSuffix: '_windows_amd64.zip' },
  { name: 'naabu', repo: 'projectdiscovery/naabu', exeName: 'naabu.exe', assetPrefix: 'naabu_', assetSuffix: '_windows_amd64.zip' },
  { name: 'katana', repo: 'projectdiscovery/katana', exeName: 'katana.exe', assetPrefix: 'katana_', assetSuffix: '_windows_amd64.zip' },
  { name: 'dnsx', repo: 'projectdiscovery/dnsx', exeName: 'dnsx.exe', assetPrefix: 'dnsx_', assetSuffix: '_windows_amd64.zip' },
  { name: 'alterx', repo: 'projectdiscovery/alterx', exeName: 'alterx.exe', assetPrefix: 'alterx_', assetSuffix: '_windows_amd64.zip' },
  { name: 'ffuf', repo: 'ffuf/ffuf', exeName: 'ffuf.exe', assetPrefix: 'ffuf_', assetSuffix: '_windows_amd64.zip' },
  { name: 'dalfox', repo: 'hahwul/dalfox', exeName: 'dalfox.exe', assetPrefix: 'dalfox_', assetSuffix: '_windows_amd64.zip' },
  { name: 'gau', repo: 'lc/gau', exeName: 'gau.exe', assetPrefix: 'gau_', assetSuffix: '_windows_amd64.zip' },
  // Python & Git Auto-Managed Tools
  { name: 'wapiti', repo: '', exeName: 'wapiti.exe', assetPrefix: '', assetSuffix: '', pipPackage: 'wapiti3' },
  { name: 'wafw00f', repo: '', exeName: 'wafw00f.exe', assetPrefix: '', assetSuffix: '', pipPackage: 'wafw00f' },
  { name: 'whatweb', repo: '', exeName: 'whatweb.exe', assetPrefix: '', assetSuffix: '', pipPackage: 'whatweb' },
  { name: 'arjun', repo: '', exeName: 'arjun.exe', assetPrefix: '', assetSuffix: '', pipPackage: 'arjun' },
  { name: 'crlfsuite', repo: '', exeName: 'crlfsuite.exe', assetPrefix: '', assetSuffix: '', pipPackage: 'crlfsuite' },
  { name: 'corsy', repo: '', exeName: 'corsy.cmd', assetPrefix: '', assetSuffix: '', gitRepo: 'https://github.com/s0md3v/Corsy.git' },
  { name: 'cmseek', repo: '', exeName: 'cmseek.cmd', assetPrefix: '', assetSuffix: '', gitRepo: 'https://github.com/Tuhinshubhra/CMSeeK.git' },
  // System Tools
  { name: 'nmap', repo: '', exeName: 'nmap.exe', assetPrefix: '', assetSuffix: '', requiresManual: true },
  { name: 'zap', repo: '', exeName: 'zap.bat', assetPrefix: '', assetSuffix: '', requiresManual: true },
];

export class DependencyService {
  private binDir: string;
  private toolsDir: string;

  constructor() {
    this.binDir = path.join(os.homedir(), 'AppData', 'Roaming', 'ReconApp', 'bin');
    this.toolsDir = path.join(os.homedir(), 'AppData', 'Roaming', 'ReconApp', 'tools');
    if (!fs.existsSync(this.binDir)) fs.mkdirSync(this.binDir, { recursive: true });
    if (!fs.existsSync(this.toolsDir)) fs.mkdirSync(this.toolsDir, { recursive: true });
    this.syncExistingBinaries();
  }

  private syncExistingBinaries(): void {
    try {
      const goBin = path.join(os.homedir(), 'go', 'bin');
      if (fs.existsSync(goBin)) {
        const goFiles = fs.readdirSync(goBin);
        for (const file of goFiles) {
          if (file.endsWith('.exe')) {
            const src = path.join(goBin, file);
            const dst = path.join(this.binDir, file);
            if (!fs.existsSync(dst)) {
              try { fs.copyFileSync(src, dst); } catch {}
            }
          }
        }
      }

      const pyDirs = [
        path.join(os.homedir(), 'AppData', 'Roaming', 'Python', 'Python314', 'Scripts'),
        path.join(os.homedir(), 'AppData', 'Local', 'Programs', 'Python', 'Python312', 'Scripts'),
        'C:\\Python314\\Scripts'
      ];
      for (const pyDir of pyDirs) {
        if (fs.existsSync(pyDir)) {
          const files = fs.readdirSync(pyDir);
          for (const file of files) {
            if (file.endsWith('.exe')) {
              const src = path.join(pyDir, file);
              const dst = path.join(this.binDir, file);
              if (!fs.existsSync(dst)) {
                try { fs.copyFileSync(src, dst); } catch {}
              }
            }
          }
        }
      }
    } catch {
      // ignore
    }
  }

  getBinPath(toolName: string): string {
    const tool = DEPENDENCIES.find(t => t.name === toolName);
    if (!tool) return toolName;

    // Check if directly in binDir
    const possible = [
      path.join(this.binDir, tool.exeName),
      path.join(this.binDir, `${tool.name}.exe`),
      path.join(this.binDir, `${tool.name}.cmd`),
      path.join(this.binDir, `${tool.name}.bat`),
    ];
    for (const p of possible) {
      if (fs.existsSync(p)) return p;
    }

    if (tool.requiresManual) {
      return tool.exeName;
    }

    return path.join(this.binDir, tool.exeName);
  }

  isInstalled(toolName: string): boolean {
    const tool = DEPENDENCIES.find(t => t.name === toolName);
    if (!tool) return false;

    // 1. Check AppData binDir
    const candidates = [
      path.join(this.binDir, tool.exeName),
      path.join(this.binDir, `${tool.name}.exe`),
      path.join(this.binDir, `${tool.name}.cmd`),
      path.join(this.binDir, `${tool.name}.bat`),
    ];
    if (candidates.some(p => fs.existsSync(p))) return true;

    // 2. Check ~/go/bin on Windows
    if (process.platform === 'win32') {
      const inGo = path.join(os.homedir(), 'go', 'bin', tool.exeName);
      if (fs.existsSync(inGo)) return true;
    }

    // 3. Check Python Scripts directory on Windows
    if (process.platform === 'win32') {
      const pythonDirs = [
        path.join(os.homedir(), 'AppData', 'Roaming', 'Python', 'Python314', 'Scripts', tool.exeName),
        path.join(os.homedir(), 'AppData', 'Roaming', 'Python', 'Python313', 'Scripts', tool.exeName),
        path.join(os.homedir(), 'AppData', 'Roaming', 'Python', 'Python312', 'Scripts', tool.exeName),
        path.join(os.homedir(), 'AppData', 'Local', 'Programs', 'Python', 'Python312', 'Scripts', tool.exeName),
        path.join('C:\\Python314', 'Scripts', tool.exeName),
      ];
      if (pythonDirs.some(p => fs.existsSync(p))) return true;
    }

    // 4. Fallback checks for nmap and zap
    if (tool.name === 'nmap') {
      if (fs.existsSync('C:\\Program Files (x86)\\Nmap\\nmap.exe') || fs.existsSync('C:\\Program Files\\Nmap\\nmap.exe')) return true;
    }
    if (tool.name === 'zap') {
      if (fs.existsSync('C:\\Program Files\\ZAP\\Zed Attack Proxy\\zap.bat')) return true;
    }

    return false;
  }

  async installTool(tool: ToolDependency, sender: Electron.WebContents): Promise<boolean> {
    if (tool.requiresManual) {
      this.sendProgress(sender, tool.name, `${tool.name} requires manual installer download.`);
      return true;
    }

    // A. Python pip package
    if (tool.pipPackage) {
      return this.installPipPackage(tool, sender);
    }

    // B. Git repository clone
    if (tool.gitRepo) {
      return this.installGitTool(tool, sender);
    }

    // C. GitHub Release download
    if (tool.repo) {
      return this.installGitHubRelease(tool, sender);
    }

    return true;
  }

  private async installPipPackage(tool: ToolDependency, sender: Electron.WebContents): Promise<boolean> {
    return new Promise((resolve) => {
      this.sendProgress(sender, tool.name, `Running pip install -U ${tool.pipPackage}...`);
      const proc = spawn('pip', ['install', '-U', tool.pipPackage!], { shell: true });
      proc.stdout?.on('data', d => this.sendProgress(sender, tool.name, d.toString().trim()));
      proc.stderr?.on('data', d => this.sendProgress(sender, tool.name, d.toString().trim()));
      proc.on('close', (code) => {
        if (code === 0) {
          this.syncExistingBinaries();
          this.sendProgress(sender, tool.name, `Successfully installed ${tool.name} via pip.`);
          resolve(true);
        } else {
          this.sendProgress(sender, tool.name, `Failed to install ${tool.name} via pip (exit ${code}).`, true);
          resolve(false);
        }
      });
      proc.on('error', (err) => {
        this.sendProgress(sender, tool.name, `Pip error: ${err.message}`, true);
        resolve(false);
      });
    });
  }

  private async installGitTool(tool: ToolDependency, sender: Electron.WebContents): Promise<boolean> {
    return new Promise((resolve) => {
      const folderName = tool.name === 'corsy' ? 'Corsy' : tool.name === 'cmseek' ? 'CMSeeK' : tool.name;
      const targetDir = path.join(this.toolsDir, folderName);
      const scriptName = tool.name === 'corsy' ? 'corsy.py' : 'cmseek.py';

      const createWrapper = () => {
        const scriptPath = path.join(targetDir, scriptName);
        if (fs.existsSync(scriptPath)) {
          const cmdContent = `@echo off\r\nset PYTHONIOENCODING=utf-8\r\npython "${scriptPath}" %*\r\n`;
          fs.writeFileSync(path.join(this.binDir, `${tool.name}.cmd`), cmdContent);
          fs.writeFileSync(path.join(this.binDir, `${tool.name}.bat`), cmdContent);
          this.sendProgress(sender, tool.name, `Ready: created ${tool.name}.cmd runner.`);
          resolve(true);
        } else {
          resolve(false);
        }
      };

      if (fs.existsSync(targetDir)) {
        createWrapper();
        return;
      }

      this.sendProgress(sender, tool.name, `Cloning ${tool.gitRepo}...`);
      const proc = spawn('git', ['clone', '--depth', '1', tool.gitRepo!, targetDir], { shell: true });
      proc.on('close', (code) => {
        if (code === 0) {
          createWrapper();
        } else {
          this.sendProgress(sender, tool.name, `Git clone failed with code ${code}.`, true);
          resolve(false);
        }
      });
      proc.on('error', (err) => {
        this.sendProgress(sender, tool.name, `Git error: ${err.message}`, true);
        resolve(false);
      });
    });
  }

  private async installGitHubRelease(tool: ToolDependency, sender: Electron.WebContents): Promise<boolean> {
    try {
      this.sendProgress(sender, tool.name, 'Fetching latest release info from GitHub...');

      const apiURL = `https://api.github.com/repos/${tool.repo}/releases/latest`;
      const response = await axios.get(apiURL, {
        headers: { 'User-Agent': 'SecOps-ReconApp' },
        timeout: 10000
      });
      const version = response.data.tag_name.replace(/^v/, '');
      const expectedAssetName = `${tool.assetPrefix}${version}${tool.assetSuffix}`;

      // Try exact match, fallback to intelligent regex asset finder
      let asset = response.data.assets.find((a: { name: string }) => a.name === expectedAssetName);
      if (!asset) {
        asset = response.data.assets.find((a: { name: string }) => {
          const name = a.name.toLowerCase();
          if (name.endsWith('.sha256') || name.endsWith('.sig') || name.endsWith('.txt') || name.endsWith('.xml') || name.endsWith('.deb') || name.endsWith('.rpm')) return false;
          if (!name.endsWith('.zip')) return false;
          if (!name.includes(tool.name.toLowerCase())) return false;
          if (!name.includes('windows') && !name.includes('win')) return false;
          if (name.includes('arm64') || name.includes('aarch64')) return false;
          return name.includes('amd64') || name.includes('x86_64') || name.includes('x64') || name.includes('64-bit') || name.includes('win64');
        });
      }

      if (!asset) {
        throw new Error(`Compatible Windows release asset not found for ${tool.name}.`);
      }

      const assetName = asset.name;
      this.sendProgress(sender, tool.name, `Downloading ${assetName}...`);

      const zipPath = path.join(this.binDir, assetName);
      await this.downloadFile(asset.browser_download_url, zipPath, (progress) => {
        this.sendProgress(sender, tool.name, `Downloading: ${Math.round(progress)}%`);
      });

      this.sendProgress(sender, tool.name, 'Extracting archive...');

      // Safe extraction
      await extract(zipPath, { dir: this.binDir });

      // Flatten binary to root binDir if extracted into a subfolder
      await this.ensureBinaryAtRoot(tool.exeName);

      // Cleanup zip
      try { await fsPromises.unlink(zipPath); } catch {}

      // If nuclei was installed, automatically update templates
      if (tool.name === 'nuclei') {
        this.sendProgress(sender, tool.name, 'Updating nuclei templates...');
        await new Promise(r => {
          exec(`"${path.join(this.binDir, 'nuclei.exe')}" -update-templates`, () => r(null));
        });
      }

      this.sendProgress(sender, tool.name, 'Installed successfully.');
      return true;

    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      logger.error(`Failed to install ${tool.name}`, errorMessage);
      this.sendProgress(sender, tool.name, `Error: ${errorMessage}`, true);
      return false;
    }
  }

  private async ensureBinaryAtRoot(exeName: string): Promise<void> {
    const rootTarget = path.join(this.binDir, exeName);
    if (fs.existsSync(rootTarget)) return;

    const findExe = (dir: string, depth = 0): string | null => {
      if (depth > 2) return null;
      try {
        const entries = fs.readdirSync(dir, { withFileTypes: true });
        for (const entry of entries) {
          const full = path.join(dir, entry.name);
          if (entry.isDirectory()) {
            const found = findExe(full, depth + 1);
            if (found) return found;
          } else if (entry.isFile() && entry.name.toLowerCase() === exeName.toLowerCase()) {
            return full;
          }
        }
      } catch {
        // ignore
      }
      return null;
    };

    const located = findExe(this.binDir);
    if (located && located !== rootTarget) {
      await fsPromises.copyFile(located, rootTarget);
      logger.info(`Relocated ${exeName} from subfolder to ${rootTarget}`);
    }
  }

  async checkAndInstallAll(sender: Electron.WebContents): Promise<void> {
    for (const tool of DEPENDENCIES) {
      if (!tool.requiresManual && !this.isInstalled(tool.name)) {
        await this.installTool(tool, sender);
      }
    }
    safeSend(sender, 'dependencies:ready', { status: 'all_installed' });
  }

  private sendProgress(sender: Electron.WebContents, tool: string, message: string, isError = false) {
    logger.info(`[Install ${tool}] ${message}`);
    safeSend(sender, 'dependency:progress', { tool, message, isError });
  }

  private async downloadFile(url: string, dest: string, onProgress: (percent: number) => void): Promise<void> {
    const response = await axios({
      method: 'GET',
      url: url,
      responseType: 'stream'
    });

    const totalLength = response.headers['content-length'];
    let downloaded = 0;

    return new Promise((resolve, reject) => {
      const writer = fs.createWriteStream(dest);
      response.data.on('data', (chunk: Buffer) => {
        downloaded += chunk.length;
        if (totalLength) {
          onProgress((downloaded / totalLength) * 100);
        }
      });
      response.data.pipe(writer);
      writer.on('finish', resolve);
      writer.on('error', reject);
    });
  }
}

export const dependencyService = new DependencyService();

// Helper to safely send IPC messages
function safeSend(sender: Electron.WebContents, channel: string, data: unknown) {
  if (sender && !sender.isDestroyed()) {
    sender.send(channel, data);
  }
}

import fs, { promises as fsPromises } from 'fs';
import path from 'path';
import os from 'os';
import { dbService } from './database';
import { logger } from './logger';
import { shell } from 'electron';

export interface ReportData {
  scanId: string;
  target: string;
  status: string;
  startTime: string;
  endTime?: string;
  toolsUsed: string[];
  findings: Array<{
    id?: string;
    scanner: string;
    name: string;
    severity: string;
    url?: string;
    description?: string;
    rawJson?: Record<string, unknown>;
  }>;
  aiAnalysis?: string;
}

export class ReportService {
  private baseDir: string;
  private reportsDir: string;

  constructor() {
    this.baseDir = path.join(os.homedir(), 'Documents', 'SecOpsScans');
    this.reportsDir = path.join(this.baseDir, 'reports');
  }

  async compileReportData(scanId: string): Promise<ReportData> {
    const scan = dbService.getScanById(scanId) || {
      scanId,
      target: 'Unknown Target',
      status: 'COMPLETED',
      startTime: new Date().toISOString(),
      config: {}
    };

    const findings = dbService.getFindings(scanId);

    // Check if AI analysis exists in scan dir
    let aiAnalysis = '';
    const aiPath = path.join(this.reportsDir, scanId, 'ai_analysis.txt');
    if (fs.existsSync(aiPath)) {
      try {
        aiAnalysis = fs.readFileSync(aiPath, 'utf8');
      } catch {
        // ignore
      }
    }

    return {
      scanId,
      target: scan.target,
      status: scan.status,
      startTime: scan.startTime,
      endTime: scan.endTime,
      toolsUsed: scan.config?.tools || [],
      findings,
      aiAnalysis
    };
  }

  calculateStats(findings: ReportData['findings']) {
    let critical = 0, high = 0, medium = 0, low = 0, info = 0;
    for (const f of findings) {
      const sev = (f.severity || 'info').toLowerCase();
      if (sev === 'critical') critical++;
      else if (sev === 'high') high++;
      else if (sev === 'medium') medium++;
      else if (sev === 'low') low++;
      else info++;
    }

    const total = findings.length;
    // Weighted risk score (0-100 max scale)
    const rawScore = (critical * 10) + (high * 6) + (medium * 3) + (low * 1);
    const riskScore = Math.min(100, rawScore);

    let grade = 'A';
    let gradeColor = '#10b981';
    if (critical > 0 || riskScore >= 50) {
      grade = 'F';
      gradeColor = '#ef4444';
    } else if (high > 1 || riskScore >= 35) {
      grade = 'D';
      gradeColor = '#f97316';
    } else if (high === 1 || medium > 3 || riskScore >= 20) {
      grade = 'C';
      gradeColor = '#f59e0b';
    } else if (medium > 0 || low > 5 || riskScore >= 10) {
      grade = 'B';
      gradeColor = '#3b82f6';
    }

    return { critical, high, medium, low, info, total, riskScore, grade, gradeColor };
  }

  async generateHtmlReport(scanId: string): Promise<string> {
    const data = await this.compileReportData(scanId);
    const stats = this.calculateStats(data.findings);
    const scanDir = path.join(this.reportsDir, scanId);
    if (!fs.existsSync(scanDir)) fs.mkdirSync(scanDir, { recursive: true });

    const reportPath = path.join(scanDir, `Executive_Report_${scanId}.html`);

    const findingsHtml = data.findings.map((f, i) => {
      const sev = (f.severity || 'info').toLowerCase();
      const sevBadgeColors: Record<string, string> = {
        critical: 'background:#f43f5e; color:#fff;',
        high: 'background:#ef4444; color:#fff;',
        medium: 'background:#f59e0b; color:#000;',
        low: 'background:#10b981; color:#fff;',
        info: 'background:#3b82f6; color:#fff;',
      };
      const badgeStyle = sevBadgeColors[sev] || 'background:#64748b; color:#fff;';

      return `
        <div style="background:#111a2e; border:1px solid #1e293b; border-radius:12px; margin-bottom:14px; padding:18px; transition:border-color 0.2s;">
          <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:10px;">
            <div style="display:flex; align-items:center; gap:10px;">
              <span style="${badgeStyle} font-size:11px; font-weight:800; padding:3px 10px; border-radius:20px; text-transform:uppercase;">${sev}</span>
              <span style="color:#f8fafc; font-weight:700; font-size:15px;">#${i + 1} - ${escapeHtml(f.name || 'Vulnerability Finding')}</span>
            </div>
            <span style="background:#1e293b; color:#94a3b8; font-family:monospace; font-size:11px; padding:4px 8px; border-radius:6px;">${escapeHtml(f.scanner)}</span>
          </div>
          ${f.url ? `<div style="font-family:monospace; font-size:12px; color:#38bdf8; margin-bottom:8px; word-break:break-all;"><strong>URL:</strong> ${escapeHtml(f.url)}</div>` : ''}
