      const script = `Start-Process -Wait -NoNewWindow -FilePath '${ctx.bin}' -ArgumentList ${opts.args.map(a => `'${a.replace(/'/g, "''")}'`).join(', ')}`;
      const encodedScript = Buffer.from(script, 'utf16le').toString('base64');
