import { useState, useEffect, useRef } from 'react';
import { Play, Square, FolderOpen, Copy, Sparkles, Globe, ShieldAlert, Download, History, ChevronDown, Check } from 'lucide-react';

interface ScannerControlsProps {
  targetUrl: string;
  setTargetUrl: (val: string) => void;
  status: string;
  scanId: string | null;
  isWordpressScan: boolean;
  setIsWordpressScan: (val: boolean) => void;
  handleStartScan: () => void;
  handleStopScan: () => void;
  handleOpenFolder: () => void;
  handleAnalyzeAI: () => void;
  handleCopyLogsForAI: () => void;
  handleUpdateTools: () => void;
  onOpenExportReport?: () => void;
  isAnalyzing: boolean;
  isUpdating: boolean;
}

const DEFAULT_TARGET_PRESETS = [
  'http://testphp.vulnweb.com',
  'http://scanme.nmap.org',
  'https://juice-shop.herokuapp.com'
];

export default function ScannerControls({
  targetUrl, setTargetUrl, status, scanId,
  isWordpressScan, setIsWordpressScan,
  handleStartScan, handleStopScan,
  handleOpenFolder, handleAnalyzeAI, handleCopyLogsForAI, handleUpdateTools,
  onOpenExportReport,
  isAnalyzing, isUpdating
}: ScannerControlsProps) {
  const isRunning = status === 'RUNNING';
  const [showHistory, setShowHistory] = useState(false);
  const [recentTargets, setRecentTargets] = useState<string[]>([]);
  const historyRef = useRef<HTMLDivElement>(null);

  // Load target history from localStorage
  useEffect(() => {
    try {
      const stored = localStorage.getItem('secops_recent_targets');
      if (stored) {
        setRecentTargets(JSON.parse(stored));
      } else {
        setRecentTargets(DEFAULT_TARGET_PRESETS);
      }
    } catch {
      setRecentTargets(DEFAULT_TARGET_PRESETS);
    }
  }, []);

  // Close dropdown on outside click
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (historyRef.current && !historyRef.current.contains(event.target as Node)) {
        setShowHistory(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const saveTargetToHistory = (url: string) => {
    if (!url || url.trim().length < 3) return;
    const clean = url.trim();
    setRecentTargets(prev => {
      const updated = [clean, ...prev.filter(t => t.toLowerCase() !== clean.toLowerCase())].slice(0, 8);
      try {
        localStorage.setItem('secops_recent_targets', JSON.stringify(updated));
      } catch {
        // ignore
      }
      return updated;
    });
  };

  const onStart = () => {
    saveTargetToHistory(targetUrl);
    handleStartScan();
  };

  return (
    <div className="theme-card p-4 rounded-2xl flex flex-col md:flex-row items-center justify-between gap-4 shadow-lg border border-[var(--border-card)]">
      {/* Target Input with Smart History Dropdown & WordPress toggle */}
      <div className="flex items-center gap-3 flex-1 w-full max-w-2xl relative" ref={historyRef}>
        <div className="relative flex-1">
          <div className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--accent-primary)] pointer-events-none">
            <Globe className="w-4 h-4" />
          </div>

          <input
            type="text"
            value={targetUrl}
            onChange={(e) => setTargetUrl(e.target.value)}
            placeholder="Target URL / Domain (e.g., example.com or https://target.com)"
            className="w-full bg-[var(--bg-app)] border border-[var(--border-card)] rounded-xl pl-10 pr-9 py-2.5 text-xs text-[var(--text-primary)] font-mono focus:outline-none focus:border-[var(--accent-primary)] focus:ring-1 focus:ring-[var(--accent-primary)] transition-all placeholder:[var(--text-muted)] shadow-inner"
            disabled={isRunning}
            onFocus={() => setShowHistory(true)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                if (!isRunning) onStart();
              }
            }}
          />

          <button
            type="button"
            onClick={() => setShowHistory(prev => !prev)}
            disabled={isRunning}
            className="absolute right-2.5 top-1/2 -translate-y-1/2 text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors p-1 cursor-pointer"
            title="Recent Targets & Presets"
          >
            <ChevronDown className={`w-3.5 h-3.5 transition-transform duration-200 ${showHistory ? 'rotate-180 text-[var(--accent-primary)]' : ''}`} />
          </button>

          {/* Recent Targets Dropdown Menu */}
          {showHistory && (
            <div className="absolute left-0 right-0 top-full mt-1.5 bg-[var(--bg-card)] border border-[var(--border-card)] rounded-xl shadow-2xl z-40 overflow-hidden backdrop-blur-xl animate-in fade-in slide-in-from-top-1 duration-150">
              <div className="p-2 border-b border-[var(--border-card)] bg-[var(--bg-surface)] flex items-center justify-between text-[11px] font-semibold text-[var(--text-muted)]">
                <span className="flex items-center gap-1.5">
                  <History className="w-3.5 h-3.5 text-[var(--accent-primary)]" />
                  Recent Targets & Test Labs
                </span>
                <span className="text-[10px] font-mono">1-Click Select</span>
              </div>
              <div className="max-h-48 overflow-y-auto p-1 font-mono text-xs space-y-0.5">
                {recentTargets.map((item, idx) => (
                  <button
                    key={idx}
                    type="button"
                    onClick={() => {
                      setTargetUrl(item);
                      setShowHistory(false);
                    }}
                    className="w-full text-left px-3 py-2 rounded-lg hover:bg-[var(--accent-primary)]/10 hover:text-[var(--accent-primary)] text-[var(--text-secondary)] transition-all flex items-center justify-between cursor-pointer group"
                  >
                    <span className="truncate">{item}</span>
                    {targetUrl === item && <Check className="w-3.5 h-3.5 text-emerald-400 shrink-0 ml-2" />}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        <label className="flex items-center gap-2 px-3.5 py-2.5 rounded-xl bg-[var(--bg-card)] border border-[var(--border-card)] hover:border-[var(--border-glow)] text-xs text-[var(--text-secondary)] hover:text-[var(--text-primary)] transition-all cursor-pointer shrink-0 select-none shadow-sm">
          <input
            type="checkbox"
            checked={isWordpressScan}
            onChange={(e) => setIsWordpressScan(e.target.checked)}
            disabled={isRunning}
            className="w-3.5 h-3.5 rounded bg-[var(--bg-app)] border-[var(--border-card)] text-[var(--accent-primary)] focus:ring-0 cursor-pointer"
          />
          <span className="font-semibold">WordPress Mode</span>
        </label>
      </div>

      {/* Action Buttons */}
      <div className="flex items-center gap-2 flex-wrap justify-end">
        {!isRunning ? (
          <button
            onClick={onStart}
            className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 text-white px-5 py-2.5 rounded-xl font-bold text-xs transition-all shadow-md shadow-emerald-900/40 hover:scale-[1.02] cursor-pointer"
          >
            <Play className="w-4 h-4 fill-white" />
            <span>START SCAN</span>
          </button>
        ) : (
          <button
            onClick={handleStopScan}
            className="flex items-center gap-2 bg-rose-600 hover:bg-rose-500 text-white px-5 py-2.5 rounded-xl font-bold text-xs transition-all shadow-md shadow-rose-900/40 hover:scale-[1.02] cursor-pointer animate-pulse"
          >
            <Square className="w-4 h-4 fill-white" />
            <span>STOP SCAN</span>
          </button>
        )}

        {/* Export Report Action */}
        <button
          onClick={onOpenExportReport}
          disabled={!scanId}
          title="Export Multi-Format Security Report"
          className="flex items-center gap-1.5 bg-[var(--bg-card)] hover:bg-[var(--accent-primary)]/10 hover:text-[var(--accent-primary)] hover:border-[var(--border-glow)] disabled:opacity-40 disabled:cursor-not-allowed text-[var(--text-secondary)] border border-[var(--border-card)] px-3.5 py-2.5 rounded-xl font-semibold text-xs transition-all cursor-pointer shadow-sm"
        >
          <Download className="w-3.5 h-3.5 text-[var(--accent-primary)]" />
          <span>Export Report</span>
        </button>

        <button
          onClick={handleOpenFolder}
          disabled={!scanId}
          className="flex items-center gap-1.5 bg-[var(--bg-card)] hover:bg-white/5 disabled:opacity-40 disabled:cursor-not-allowed text-[var(--text-secondary)] hover:text-[var(--text-primary)] border border-[var(--border-card)] px-3 py-2.5 rounded-xl font-medium text-xs transition-all cursor-pointer"
          title="Open Report Folder in Explorer"
        >
          <FolderOpen className="w-3.5 h-3.5 text-cyan-400" />
          <span className="hidden xl:inline">Artifacts</span>
        </button>

        <button
          onClick={handleAnalyzeAI}
          disabled={!scanId || isAnalyzing}
          title="Analyze console logs with AI Security Analyst"
          className="flex items-center gap-1.5 bg-purple-600/90 hover:bg-purple-600 disabled:opacity-40 disabled:cursor-not-allowed text-white px-3.5 py-2.5 rounded-xl font-semibold text-xs transition-all shadow-sm shadow-purple-900/20 cursor-pointer"
        >
          <Sparkles className={`w-3.5 h-3.5 ${isAnalyzing ? 'animate-spin' : ''}`} />
          <span>{isAnalyzing ? 'Analyzing...' : 'AI Analyst'}</span>
        </button>

        <button
          onClick={handleCopyLogsForAI}
          disabled={!scanId}
          title="Copy raw scan logs formatted for LLM context"
          className="flex items-center gap-1.5 bg-[var(--bg-card)] hover:bg-white/5 disabled:opacity-40 disabled:cursor-not-allowed text-[var(--text-secondary)] hover:text-[var(--text-primary)] border border-[var(--border-card)] px-3 py-2.5 rounded-xl font-medium text-xs transition-all cursor-pointer"
        >
          <Copy className="w-3.5 h-3.5" />
          <span className="hidden xl:inline">Copy Logs</span>
        </button>

        <button
          onClick={handleUpdateTools}
          disabled={isUpdating}
          className="flex items-center gap-1.5 bg-[var(--bg-card)] hover:border-[var(--border-glow)] text-[var(--text-primary)] border border-[var(--border-card)] px-3.5 py-2.5 rounded-xl font-semibold text-xs transition-all cursor-pointer shadow-sm"
        >
          <ShieldAlert className="w-3.5 h-3.5 text-amber-400" />
          <span>Tools Hub</span>
        </button>
      </div>
    </div>
  );
}

