import React, { useState, useEffect, useRef } from 'react';
import { 
  X, RefreshCw, Download, CheckCircle2, AlertTriangle, 
  XCircle, Terminal, Shield, Zap, Search, Globe, ShieldAlert, Cpu, Sparkles
} from 'lucide-react';
import type { ToolHealthInfo } from '../types/global';

interface ToolsHubModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ToolsHubModal: React.FC<ToolsHubModalProps> = ({ isOpen, onClose }) => {
  const [tools, setTools] = useState<ToolHealthInfo[]>([]);
  const [loading, setLoading] = useState(false);
  const [updatingTool, setUpdatingTool] = useState<string | null>(null);
  const [isUpdatingAll, setIsUpdatingAll] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState<string>('');
  const logContainerRef = useRef<HTMLDivElement>(null);

  const fetchHealth = async () => {
    if (!window.api?.getToolsHealth) return;
    setLoading(true);
    try {
      const data = await window.api.getToolsHealth();
      setTools(data);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      setLogs((prev) => [...prev, `[-] Error loading health matrix: ${msg}`]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isOpen) {
      fetchHealth();
    }
  }, [isOpen]);

  // IPC listener for update progress
  useEffect(() => {
    if (!window.api?.onToolUpdateProgress) return;

    const removeProgressListener = window.api.onToolUpdateProgress((_event, data) => {
      setLogs((prev) => [...prev, data.message]);
      if (logContainerRef.current) {
        logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
      }
    });

    const removeStatusListener = window.api.onToolUpdateStatus?.((_event, status) => {
      if (status === 'DONE') {
        setIsUpdatingAll(false);
        setUpdatingTool(null);
        fetchHealth();
      }
    });

    return () => {
      removeProgressListener();
      removeStatusListener?.();
    };
  }, []);

  const handleUpdateSingle = async (toolName: string) => {
    if (updatingTool || isUpdatingAll) return;
    setUpdatingTool(toolName);
    setLogs((prev) => [...prev, `\n[*] Initiating update for ${toolName}...`]);
    try {
      await window.api.updateTool(toolName);
      await fetchHealth();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      setLogs((prev) => [...prev, `[-] Update failed for ${toolName}: ${msg}`]);
    } finally {
      setUpdatingTool(null);
    }
  };

  const handleUpdateAll = async () => {
    if (isUpdatingAll || updatingTool) return;
    setIsUpdatingAll(true);
    setLogs((prev) => [...prev, `\n[*] Starting Master Suite Update...`]);
    try {
      await window.api.updateAllTools();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      setLogs((prev) => [...prev, `[-] Master update encountered error: ${msg}`]);
      setIsUpdatingAll(false);
    }
  };

  const filteredTools = tools.filter((t) => {
    const matchesCat = filterCategory === 'all' || t.category === filterCategory;
    const matchesSearch = 
      t.displayName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      t.name.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCat && matchesSearch;
  });

  const readyCount = tools.filter((t) => t.installed).length;
  const updateCount = tools.filter((t) => t.updateAvailable).length;

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
      <div className="w-full max-w-5xl max-h-[90vh] bg-[var(--bg-surface)] border border-[var(--border-card)] rounded-2xl shadow-2xl flex flex-col overflow-hidden theme-card">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-[var(--border-card)] bg-[var(--bg-card)]">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-[var(--accent-primary)]/10 border border-[var(--border-glow)]">
              <Cpu className="w-6 h-6 text-[var(--accent-primary)]" />
            </div>
            <div>
              <h2 className="text-lg font-bold text-[var(--text-primary)] tracking-tight">
                Engines & Security Tool Suite
              </h2>
              <p className="text-xs text-[var(--text-secondary)]">
                Manage, update, and auto-download ProjectDiscovery tools, Nuclei templates, and Wapiti.
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2.5">
            <button
              onClick={fetchHealth}
              disabled={loading || isUpdatingAll}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-xl bg-[var(--bg-card)] border border-[var(--border-card)] hover:border-[var(--border-glow)] text-[var(--text-secondary)] hover:text-[var(--text-primary)] transition-all cursor-pointer disabled:opacity-50"
              title="Refresh version matrix"
            >
              <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
              <span>Refresh</span>
            </button>

            <button
              onClick={handleUpdateAll}
              disabled={isUpdatingAll || !!updatingTool}
              className="flex items-center gap-2 px-4 py-1.5 text-xs font-bold rounded-xl bg-[var(--accent-primary)] text-white hover:bg-[var(--accent-hover)] shadow-md shadow-[var(--accent-glow)] transition-all cursor-pointer disabled:opacity-50"
            >
              <Sparkles className={`w-3.5 h-3.5 ${isUpdatingAll ? 'animate-spin' : ''}`} />
              <span>{isUpdatingAll ? 'Updating All...' : 'Update All Engines & Templates'}</span>
            </button>

            <button
              onClick={onClose}
              className="p-1.5 rounded-xl text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-white/5 transition-colors cursor-pointer ml-1"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Telemetry Bar */}
        <div className="grid grid-cols-3 gap-4 px-6 py-3 border-b border-[var(--border-card)] bg-black/10 text-xs">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4 text-emerald-400" />
            <span className="text-[var(--text-muted)]">Installed & Ready:</span>
            <span className="font-mono font-bold text-[var(--text-primary)]">{readyCount} / {tools.length}</span>
          </div>
          <div className="flex items-center gap-2">
            <AlertTriangle className="w-4 h-4 text-amber-400" />
            <span className="text-[var(--text-muted)]">Updates Available:</span>
            <span className="font-mono font-bold text-amber-400">{updateCount}</span>
          </div>
          <div className="flex items-center gap-2">
            <Shield className="w-4 h-4 text-[var(--accent-primary)]" />
            <span className="text-[var(--text-muted)]">Template Status:</span>
            <span className="font-mono font-bold text-emerald-400">Nuclei Auto-Sync</span>
          </div>
        </div>

        {/* Filter and Search Bar */}
        <div className="flex items-center justify-between px-6 py-2.5 border-b border-[var(--border-card)] bg-[var(--bg-surface)]">
          <div className="flex items-center gap-1.5">
            {['all', 'dast', 'recon', 'fuzz', 'network'].map((cat) => (
              <button
                key={cat}
                onClick={() => setFilterCategory(cat)}
                className={`px-3 py-1 rounded-lg text-xs font-medium uppercase tracking-wider transition-all cursor-pointer ${
                  filterCategory === cat
                    ? 'bg-[var(--accent-primary)] text-white shadow-sm'
                    : 'text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-white/5'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>

          <div className="flex items-center bg-[var(--bg-card)] rounded-xl px-3 py-1 border border-[var(--border-card)] focus-within:border-[var(--accent-primary)] transition-all">
            <Search className="w-3.5 h-3.5 text-[var(--text-muted)] mr-2" />
            <input
              type="text"
              placeholder="Filter tools..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="bg-transparent border-none text-xs text-[var(--text-primary)] outline-none w-40 placeholder-[var(--text-muted)]"
            />
          </div>
        </div>

        {/* Tools Matrix Table */}
        <div className="flex-1 overflow-y-auto px-6 py-4">
          <table className="w-full text-left border-collapse text-xs">
            <thead>
              <tr className="border-b border-[var(--border-card)] text-[var(--text-muted)] font-mono uppercase tracking-wider">
                <th className="py-2.5 px-3">Tool Name</th>
                <th className="py-2.5 px-3">Category</th>
                <th className="py-2.5 px-3">Installed Version</th>
                <th className="py-2.5 px-3">Latest Release</th>
                <th className="py-2.5 px-3">Path / Location</th>
                <th className="py-2.5 px-3 text-right">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--border-card)]/50">
              {filteredTools.map((t) => {
                const isThisUpdating = updatingTool === t.name || isUpdatingAll;
                return (
                  <tr key={t.name} className="hover:bg-white/[0.02] transition-colors">
                    <td className="py-3 px-3 font-semibold text-[var(--text-primary)]">
                      <div className="flex items-center gap-2">
                        {t.category === 'dast' ? (
                          <ShieldAlert className="w-4 h-4 text-amber-400" />
                        ) : t.category === 'recon' ? (
                          <Globe className="w-4 h-4 text-cyan-400" />
                        ) : t.category === 'fuzz' ? (
                          <Zap className="w-4 h-4 text-purple-400" />
                        ) : (
                          <Terminal className="w-4 h-4 text-emerald-400" />
                        )}
                        <span>{t.displayName}</span>
                      </div>
                    </td>

                    <td className="py-3 px-3">
                      <span className="px-2 py-0.5 rounded-full text-[10px] font-mono uppercase font-medium bg-black/20 border border-[var(--border-card)] text-[var(--text-secondary)]">
                        {t.category}
                      </span>
                    </td>

                    <td className="py-3 px-3 font-mono">
                      {t.installed ? (
                        <span className="flex items-center gap-1.5 text-emerald-400">
                          <CheckCircle2 className="w-3.5 h-3.5" />
                          <span>{t.currentVersion}</span>
                        </span>
                      ) : (
                        <span className="flex items-center gap-1.5 text-rose-400">
                          <XCircle className="w-3.5 h-3.5" />
                          <span>Not Installed</span>
                        </span>
                      )}
                    </td>

                    <td className="py-3 px-3 font-mono">
                      <span className={t.updateAvailable ? 'text-amber-400 font-bold' : 'text-[var(--text-secondary)]'}>
                        {t.latestVersion}
                      </span>
                    </td>

                    <td className="py-3 px-3 font-mono text-[11px] text-[var(--text-muted)] max-w-xs truncate" title={t.resolvedPath}>
                      {t.resolvedPath}
                    </td>

                    <td className="py-3 px-3 text-right">
                      {t.requiresManual ? (
                        <span className="text-[11px] text-[var(--text-muted)] italic">Manual Install</span>
                      ) : (
                        <button
                          onClick={() => handleUpdateSingle(t.name)}
                          disabled={isThisUpdating}
                          className={`inline-flex items-center gap-1 px-3 py-1 rounded-lg text-xs font-medium transition-all cursor-pointer disabled:opacity-50 ${
                            t.updateAvailable
                              ? 'bg-amber-500/20 text-amber-300 border border-amber-500/40 hover:bg-amber-500/30'
                              : 'bg-[var(--bg-card)] text-[var(--text-secondary)] border border-[var(--border-card)] hover:border-[var(--border-glow)] hover:text-[var(--text-primary)]'
                          }`}
                        >
                          <Download className={`w-3 h-3 ${isThisUpdating ? 'animate-bounce' : ''}`} />
                          <span>{isThisUpdating ? 'Updating...' : t.updateAvailable ? 'Update' : t.installed ? 'Reinstall' : 'Install'}</span>
                        </button>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        {/* Live Output Log Console */}
        {logs.length > 0 && (
          <div className="border-t border-[var(--border-card)] bg-[var(--term-bg)] flex flex-col h-44 shrink-0">
            <div className="flex items-center justify-between px-4 py-1.5 bg-black/30 border-b border-[var(--border-card)] text-[11px] font-mono text-[var(--text-muted)]">
              <span className="flex items-center gap-2 text-emerald-400 font-bold">
                <Terminal className="w-3.5 h-3.5" />
                <span>ENGINE CONSOLE OUTPUT</span>
              </span>
              <button
                onClick={() => setLogs([])}
                className="hover:text-[var(--text-primary)] transition-colors cursor-pointer"
              >
                Clear Output
              </button>
            </div>
            <div
              ref={logContainerRef}
              className="flex-1 p-3 font-mono text-[11px] text-[var(--term-fg)] overflow-y-auto whitespace-pre-wrap leading-relaxed select-text"
            >
              {logs.join('\n')}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import { useEffect, useState } from 'react';
import { RefreshCw, X, ShieldAlert, Loader2, Sparkles, Terminal, CheckCircle2, AlertCircle } from 'lucide-react';
import TerminalPane from '../components/TerminalPane';
import VulnerabilityTable from '../components/VulnerabilityTable';
import ScannerControls from '../components/ScannerControls';
import ToolSelection from '../components/ToolSelection';
import FindingsSummary from '../components/FindingsSummary';
import { ExportReportModal } from '../components/ExportReportModal';
import type { Vulnerability } from '../types/vulnerability';
import { useScanStore, allTools, initialScannerStatus } from '../stores/useScanStore';
import type { ScannerType, ScannerStatus } from '../stores/useScanStore';
import { useConfigStore } from '../stores/useConfigStore';
import { useLogStore } from '../stores/useLogStore';

export default function Dashboard({ onOpenToolsHub }: { onOpenToolsHub?: () => void } = {}) {
  const {
    targetUrl, setTargetUrl,
    scanId, setScanId,
    activeTab, setActiveTab,
    isWordpressScan, setIsWordpressScan,
    selectedTools, setSelectedTools,
    status, setStatus,
    scannerStatus, setScannerStatus,
    allFindings, setAllFindings,
    nucleiFindings, setNucleiFindings,
    wapitiVulns, setWapitiVulns,
    wapitiPages, setWapitiPages,
  } = useScanStore();

  const {
    dependencies, setDependencies,
    showDependencyModal, setShowDependencyModal,
    isInstallingDependencies, setIsInstallingDependencies,
    dependencyLogs, setDependencyLogs,
    isUpdating, setIsUpdating,
    updateLogs, setUpdateLogs,
    showUpdateModal, setShowUpdateModal,
  } = useConfigStore();

  const {
    appendRawLogs, clearRawLogs,
    aiResponse, setAiResponse,
    isAnalyzing, setIsAnalyzing,
    aiProgressMsg, setAiProgressMsg,
  } = useLogStore();

  const [showExportModal, setShowExportModal] = useState(false);
  const [consoleFilter, setConsoleFilter] = useState<'selected' | 'dast' | 'recon' | 'network' | 'all'>('selected');

  const allToolsArray = allTools;
  const tabs = [
    'findings', 'ai', 'nuclei', 'wapiti', 'wpscan', 'pdiscovery', 
    'dalfox', 'wafw00f', 'whatweb', 'arjun', 'corsy', 'cmseek', 'gau', 'crlfsuite', 
    'nmap', 'zap', 'ffuf', 'appscan', 'netsparker', 'acunetix'
  ];

  // Tool categories for console filtering
  const toolCategories = {
    dast: ['nuclei', 'wapiti', 'dalfox', 'corsy', 'cmseek', 'crlfsuite', 'zap', 'appscan', 'netsparker', 'acunetix'],
    recon: ['subfinder', 'httpx', 'katana', 'dnsx', 'alterx', 'tlsx', 'gau', 'whatweb', 'wafw00f', 'wpscan', 'pdiscovery'],
    network: ['naabu', 'nmap', 'ffuf', 'arjun']
  };

  // Scan output and stats listeners
  useEffect(() => {
    if (!scanId || !window.api) return;

    const handleOutput = (_event: unknown, data: { scanId: string; scanner: string; type: string; message: string }) => {
      if (data.scanId !== scanId) return;
      useLogStore.getState().appendRawLogs(`[${data.scanner.toUpperCase()}] ${data.message}\n`);
      useLogStore.getState().appendScannerLog(data.scanner, data.message);
    };

    const handleStats = (_event: unknown, data: { scanId: string; stats: { nuclei: Record<string, number>, wapiti: { vulns: number, pages: number } } }) => {
      if (data.scanId !== scanId) return;
      useScanStore.getState().setNucleiFindings(data.stats.nuclei as any);
      useScanStore.getState().setWapitiVulns(data.stats.wapiti.vulns);
      useScanStore.getState().setWapitiPages(data.stats.wapiti.pages);
    };

    const removeOutputListener = window.api.onScanOutput(handleOutput);
    const removeStatsListener = window.api.onScanStats(handleStats);
    const removeAiProgress = window.api.onAiProgress((_e, msg) => useLogStore.getState().setAiProgressMsg(msg));

    return () => {
      removeOutputListener();
      removeStatsListener();
      removeAiProgress();
    };
  }, [scanId]);

  // Scan status listener
  useEffect(() => {
    if (!scanId || !window.api) return;

    const handleStatus = (_event: unknown, data: { scanId: string; scanner: string; status: string }) => {
      if (data.scanId !== scanId) return;
      const scanner = data.scanner as ScannerType;

      useScanStore.getState().setScannerStatus(prev => {
        const next = { ...prev, [scanner]: data.status };
        // Aggregate pdiscovery status
        const pdTools = ['subfinder', 'httpx', 'alterx', 'dnsx', 'naabu', 'tlsx', 'katana'];
        if (pdTools.includes(scanner)) {
          const pdStatuses = pdTools.map(t => next[t as ScannerType] || 'IDLE');
          if (pdStatuses.some(s => s === 'FAILED')) next.pdiscovery = 'FAILED';
          else if (pdStatuses.some(s => s === 'RUNNING')) next.pdiscovery = 'RUNNING';
          else if (pdStatuses.every(s => ['COMPLETED', 'IDLE', 'STOPPED'].includes(s))) next.pdiscovery = 'COMPLETED';
        }

        // Check if all requested tools are done
        const terminal = ['COMPLETED', 'FAILED', 'STOPPED', 'IDLE'];
        const allDone = Object.values(next).every(s => terminal.includes(s as string));
        const anyFailed = Object.values(next).some(s => s === 'FAILED');

        const currentStatus = useScanStore.getState().status;
        if (allDone && currentStatus !== 'IDLE') {
          useScanStore.getState().setStatus(anyFailed ? 'FAILED' : 'COMPLETED');
        }

        return next;
      });
    };

    const handleFindings = (_event: unknown, data: { scanId: string; scanner: string; findings: Vulnerability[] }) => {
      if (data.scanId !== scanId) return;
      useScanStore.getState().setAllFindings(prev => [...prev, ...data.findings]);
    };

    const removeStatusListener = window.api.onScanStatus(handleStatus);
    const removeFindingsListener = window.api.onScanFindings(handleFindings);

    return () => {
      removeStatusListener();
      removeFindingsListener();
    };
  }, [scanId]);

  // Updater listeners
  useEffect(() => {
    if (!window.api) return;

    const handleUpdateOutput = (_event: unknown, msg: string) => {
      useConfigStore.getState().setUpdateLogs(prev => [...prev, msg]);
    };

    const handleUpdateStatus = (_event: unknown, newStatus: string) => {
      if (newStatus === 'DONE' || newStatus === 'ERROR') {
        useConfigStore.getState().setIsUpdating(false);
      }
    };

    const removeOutput = window.api.onUpdateOutput(handleUpdateOutput);
    const removeStatus = window.api.onUpdateStatus(handleUpdateStatus);

    return () => {
      removeOutput();
      removeStatus();
    };
  }, []);

  // Dependency checkers
  useEffect(() => {
    if (!window.api) return;

    // Initial check
    window.api.checkDependencies().then(deps => {
      useConfigStore.getState().setDependencies(deps);
      const missing = deps.filter(d => !d.isInstalled);
      if (missing.length > 0) {
        useConfigStore.getState().setShowDependencyModal(true);
      }
    });

    // Listen to progress
    const removeInstallProgress = window.api.onInstallProgress((_e, msg) => {
      useConfigStore.getState().setDependencyLogs(prev => [...prev, msg]);
    });

    return () => {
      removeInstallProgress();
    };
  }, []);

  const handleInstallDependencies = async () => {
    setIsInstallingDependencies(true);
    setDependencyLogs([]);
    try {
      await window.api.installDependencies();
      // Re-check
      const deps = await window.api.checkDependencies();
      setDependencies(deps);
      setTimeout(() => {
        setIsInstallingDependencies(false);
      }, 1500);
    } catch (err: unknown) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      setDependencyLogs(prev => [...prev, `Error: ${errorMessage}`]);
      setIsInstallingDependencies(false);
    }
  };

  const validateUrl = (url: string) => {
    try {
      const parsed = new URL(url.startsWith('http') ? url : `https://${url}`);
      if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return false;
      if (/['";&|$<>]/.test(parsed.hostname)) return false;
      return true;
    } catch {
      return false;
    }
  };

  const handleStartScan = async () => {
    let finalUrl = targetUrl.trim();
    if (!finalUrl.startsWith('http')) {
      finalUrl = `https://${finalUrl}`;
      setTargetUrl(finalUrl);
    }

    if (!validateUrl(finalUrl)) {
      alert('Please enter a valid URL');
      return;
    }

    // Reset findings
    setNucleiFindings({ info: 0, low: 0, medium: 0, high: 0, critical: 0 });
    setWapitiVulns(0);
    setWapitiPages(0);
    setAllFindings([]);
    clearRawLogs();
    appendRawLogs(`Scan started against ${finalUrl} at ${new Date().toISOString()}\n\n`);

    setStatus('STARTING');
    const initialStatus: Record<ScannerType, ScannerStatus> = { ...initialScannerStatus };

    selectedTools.forEach(tool => {
      initialStatus[tool as ScannerType] = 'RUNNING';
      if (['subfinder', 'httpx', 'alterx', 'dnsx', 'naabu', 'tlsx', 'katana'].includes(tool)) {
        initialStatus.pdiscovery = 'RUNNING';
      }
    });

    setScannerStatus(initialStatus);

    try {
      const res = await window.api.startScan(finalUrl, {
        tools: selectedTools,
        isWordpress: isWordpressScan
      });
      if (res.success) {
        setScanId(res.scanId || null);
        setStatus('RUNNING');
      } else {
        alert('Failed to start scan: ' + res.error);
        setStatus('FAILED');
        setScannerStatus(initialScannerStatus);
      }
    } catch (e: unknown) {
      const errorMessage = e instanceof Error ? e.message : String(e);
      alert('Error: ' + errorMessage);
      setStatus('FAILED');
    }
  };

  const handleStopScan = async () => {
    if (!scanId) return;
    setStatus('STOPPING');
    const res = await window.api.stopScan(scanId);
    if (res.success) {
      setStatus('STOPPED');
      setScannerStatus(prev => {
        const next = { ...prev };
        for (const k in next) if (next[k as ScannerType] === 'RUNNING') next[k as ScannerType] = 'STOPPED';
        return next;
      });
    }
  };

  const handleOpenFolder = () => {
    if (scanId) {
      window.api.openReportFolder(scanId);
    }
  };

  const handleCopyLogsForAI = () => {
    const logs = useLogStore.getState().rawLogs;
    if (!logs) {
      alert('No logs available yet.');
      return;
    }
    const contextText = `# SecOps Recon Scan Logs\n\nTarget: ${targetUrl}\nStatus: ${status}\n\n## Terminal Output\n\`\`\`\n${logs}\n\`\`\`\n`;
    navigator.clipboard.writeText(contextText);
    alert('Full scan logs copied! You can now paste this to your AI agent.');
  };

  const handleAnalyzeAI = async () => {
    const logs = useLogStore.getState().rawLogs;
    if (!logs) {
      alert('No logs available to analyze.');
      return;
    }
    setActiveTab('ai');
    setIsAnalyzing(true);
    setAiResponse('');
    setAiProgressMsg('Synthesizing engine findings with AI Security Analyst...');

    try {
      const prompt = `You are a Principal Cyber Security Analyst. Analyze these automated scan logs for ${targetUrl}. Summarize the vulnerabilities, prioritize top critical risks, and suggest concrete remediation steps. Provide a clear, actionable executive report.`;
      const response = await window.api.analyzeLogs(logs, prompt);
      setAiResponse(response);
    } catch (err: unknown) {
      let msg = err instanceof Error ? err.message : String(err);
      if (msg.includes('Is Ollama running?')) {
        msg = `Could not connect to Ollama. Please ensure Ollama is running locally, or configure an alternative AI Provider in Settings.\n\nTechnical details: ${(err as Error).message}`;
      } else {
        msg = `Error during AI Analysis:\n\n${(err as Error).message}\n\nPlease check your configuration in Settings.`;
      }
      setAiResponse(`[ERROR]\n${msg}`);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleUpdateTools = async () => {
    if (onOpenToolsHub) {
      onOpenToolsHub();
      return;
    }
    setIsUpdating(true);
    setUpdateLogs([]);
    setShowUpdateModal(true);
    try {
      await window.api.updateTools();
    } catch (e: unknown) {
      const errorMessage = e instanceof Error ? e.message : String(e);
      setUpdateLogs(prev => [...prev, `Error: ${errorMessage}`]);
      setIsUpdating(false);
    }
  };

  // Determine consoles to show in the switcher bar
  const consoleTools = tabs.filter(t => t !== 'findings' && t !== 'ai').filter(tool => {
    if (consoleFilter === 'selected') {
      return selectedTools.includes(tool) || scannerStatus[tool as ScannerType] === 'RUNNING';
    }
    if (consoleFilter === 'dast') return toolCategories.dast.includes(tool);
    if (consoleFilter === 'recon') return toolCategories.recon.includes(tool);
    if (consoleFilter === 'network') return toolCategories.network.includes(tool);
    return true; // 'all'
  });

  return (
    <div className="flex flex-col h-full space-y-4">
      {/* Header Controls */}
      <ScannerControls
        targetUrl={targetUrl} setTargetUrl={setTargetUrl}
        status={status} scanId={scanId}
        isWordpressScan={isWordpressScan} setIsWordpressScan={setIsWordpressScan}
        handleStartScan={handleStartScan} handleStopScan={handleStopScan}
        handleOpenFolder={handleOpenFolder} handleAnalyzeAI={handleAnalyzeAI}
        handleCopyLogsForAI={handleCopyLogsForAI} handleUpdateTools={handleUpdateTools}
        onOpenExportReport={() => setShowExportModal(true)}
        isAnalyzing={isAnalyzing} isUpdating={isUpdating}
      />

      {/* Tool Selection Section */}
      <ToolSelection
        allTools={allToolsArray} selectedTools={selectedTools}
        setSelectedTools={setSelectedTools} status={status}
      />

      {/* Master Workspace Bar: Primary Tabs + Live Console Switcher */}
      <div className="theme-card p-2 rounded-2xl flex flex-col md:flex-row md:items-center justify-between gap-3 shadow-md border border-[var(--border-card)]">
        {/* Left: Primary Workspaces */}
        <div className="flex items-center gap-1.5 flex-wrap">
          <button
            onClick={() => setActiveTab('findings')}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 cursor-pointer ${
              activeTab === 'findings'
                ? 'bg-[var(--accent-primary)] text-white shadow-md shadow-[var(--accent-glow)]'
                : 'text-[var(--text-secondary)] hover:bg-white/5 hover:text-[var(--text-primary)]'
            }`}
          >
            <ShieldAlert className="w-4 h-4 text-rose-400" />
            <span>Findings & Vulns</span>
            {allFindings.length > 0 && (
              <span className="bg-rose-500 text-white text-[10px] px-1.5 py-0.2 rounded-full font-mono font-bold shadow-sm">
                {allFindings.length}
              </span>
            )}
          </button>

          <button
            onClick={() => setActiveTab('ai')}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 cursor-pointer ${
              activeTab === 'ai'
                ? 'bg-purple-600 text-white shadow-md shadow-purple-900/40'
                : 'text-[var(--text-secondary)] hover:bg-white/5 hover:text-[var(--text-primary)]'
            }`}
          >
            <Sparkles className="w-4 h-4 text-purple-300" />
            <span>AI Security Analyst</span>
          </button>
        </div>

        {/* Right: Console Streams Filter & Navigation */}
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 md:pb-0 scrollbar-none">
          <div className="flex items-center gap-1 bg-[var(--bg-surface)] p-1 rounded-xl border border-[var(--border-card)]">
            <span className="text-[10px] font-mono text-[var(--text-muted)] uppercase tracking-wider px-1.5 hidden sm:inline">Consoles:</span>

            {(['selected', 'dast', 'recon', 'network', 'all'] as const).map(filterKey => (
              <button
                key={filterKey}
                onClick={() => setConsoleFilter(filterKey)}
                className={`px-2 py-0.5 rounded-lg text-[10px] font-mono uppercase tracking-wider transition-all cursor-pointer ${
                  consoleFilter === filterKey
                    ? 'bg-[var(--accent-primary)]/20 text-[var(--accent-primary)] font-bold border border-[var(--border-glow)]'
                    : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'
                }`}
              >
                {filterKey === 'selected' ? 'Active' : filterKey}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Sub-bar: Active Engine Console Tabs */}
      <div className="flex items-center gap-1.5 overflow-x-auto pb-1 scrollbar-thin px-1">
        {consoleTools.map(tab => {
          const isActive = activeTab === tab;
          const scannerStat = scannerStatus[tab as ScannerType];
          const isRunning = scannerStat === 'RUNNING';
          const isFailed = scannerStat === 'FAILED';
          const isCompleted = scannerStat === 'COMPLETED';

          return (
            <button
              key={tab}
              onClick={() => setActiveTab(tab as ScannerType)}
              className={`px-3 py-1.5 rounded-xl font-mono text-xs uppercase tracking-wider font-semibold transition-all flex items-center gap-1.5 border whitespace-nowrap cursor-pointer ${
                isActive
                  ? 'bg-[var(--accent-primary)]/20 text-[var(--accent-primary)] border-[var(--border-glow)] shadow-sm'
                  : 'bg-[var(--bg-card)] text-[var(--text-muted)] border-[var(--border-card)] hover:text-[var(--text-primary)] hover:border-[var(--text-muted)]'
              }`}
            >
              {isRunning && (
                <span className="relative flex h-2 w-2">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
                </span>
              )}
              {isCompleted && <CheckCircle2 className="w-3 h-3 text-emerald-400" />}
              {isFailed && <AlertCircle className="w-3 h-3 text-rose-400" />}
              {!isRunning && !isCompleted && !isFailed && <Terminal className="w-3 h-3 opacity-50" />}
              <span>{tab}</span>
            </button>
          );
        })}
      </div>

      {/* Workspaces & Scanners Tab View Area */}
      <div className="flex-1 min-h-0 relative">
        {/* Findings View */}
        <div className={`absolute inset-0 ${activeTab === 'findings' ? 'block z-10' : 'hidden'}`}>
          <VulnerabilityTable 
            scanId={scanId} 
            refreshTrigger={allFindings.length} 
            onOpenExportReport={() => setShowExportModal(true)}
          />
        </div>

        {/* AI Security Analyst View */}
        <div className={`absolute inset-0 bg-[var(--bg-card)] border border-[var(--border-card)] rounded-2xl p-6 overflow-y-auto ${activeTab === 'ai' ? 'block z-10' : 'hidden'}`}>
          <div className="max-w-4xl mx-auto space-y-6">
            <div className="flex items-center space-x-3 pb-4 border-b border-[var(--border-card)]">
              <div className="p-2.5 rounded-xl bg-purple-500/10 border border-purple-500/20 text-purple-400 shadow-[0_0_15px_rgba(168,85,247,0.2)]">
                <Sparkles className="w-6 h-6 animate-pulse" />
              </div>
              <div>
                <h2 className="text-xl font-bold bg-gradient-to-r from-purple-400 via-pink-400 to-indigo-400 bg-clip-text text-transparent">
                  AI Security Analyst Engine
                </h2>
                <p className="text-xs text-[var(--text-muted)]">Automated correlation, threat intelligence analysis, and guided remediation matrix</p>
              </div>
            </div>

            {isAnalyzing ? (
              <div className="flex items-center space-x-3 text-purple-400 p-8 bg-[var(--bg-surface)] rounded-2xl border border-purple-500/30 shadow-lg">
                <Loader2 className="w-6 h-6 animate-spin shrink-0 text-purple-400" />
                <span className="animate-pulse text-sm font-medium">{aiProgressMsg}</span>
              </div>
            ) : aiResponse ? (
              <div className="prose prose-invert max-w-none">
                <pre className="whitespace-pre-wrap bg-[var(--bg-surface)] p-6 rounded-2xl text-[var(--text-secondary)] font-mono text-xs border border-[var(--border-card)] shadow-inner leading-relaxed">
                  {aiResponse}
                </pre>
              </div>
            ) : (
              <div className="text-center py-12 px-4 rounded-2xl bg-[var(--bg-surface)]/50 border border-dashed border-[var(--border-card)]">
                <Sparkles className="w-10 h-10 text-[var(--text-muted)] mx-auto mb-3 opacity-40" />
                <p className="text-sm font-medium text-[var(--text-secondary)]">Ready for Intelligence Analysis</p>
                <p className="text-xs text-[var(--text-muted)] mt-1 max-w-md mx-auto">
                  Run a multi-tool scan and click <span className="text-[var(--accent-primary)] font-semibold">"AI Analyst"</span> in the command bar to synthesize findings into actionable triage reports.
                </p>
              </div>
            )}
          </div>
        </div>

        {/* Terminal Consoles */}
        {tabs.filter(t => t !== 'findings' && t !== 'ai').map(tab => (
          <div key={tab} className={`absolute inset-0 transition-opacity duration-200 ${activeTab === tab ? 'opacity-100 z-10' : 'opacity-0 pointer-events-none z-0'}`}>
            <TerminalPane
              title={`${tab.charAt(0).toUpperCase() + tab.slice(1)} Console`}
              scanner={tab as ScannerType}
              scanId={scanId}
              status={scannerStatus[tab as ScannerType]}
              isVisible={activeTab === tab}
            />
          </div>
        ))}
      </div>

      {/* Findings Summary Area */}
      <FindingsSummary 
        nucleiFindings={nucleiFindings} 
        wapitiVulns={wapitiVulns} 
        wapitiPages={wapitiPages} 
      />

      {/* Export Report Modal */}
      <ExportReportModal
        isOpen={showExportModal}
        onClose={() => setShowExportModal(false)}
        scanId={scanId}
        targetUrl={targetUrl}
      />

      {/* Update Tools Modal */}
      {showUpdateModal && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-[var(--bg-card)] rounded-2xl border border-[var(--border-card)] shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[80vh]">
            <div className="p-4 border-b border-[var(--border-card)] flex items-center justify-between bg-[var(--bg-surface)]">
              <h2 className="text-sm font-bold text-[var(--text-primary)] flex items-center space-x-2">
                <RefreshCw className={`w-4 h-4 ${isUpdating ? 'animate-spin text-[var(--accent-primary)]' : 'text-[var(--text-muted)]'}`} />
                <span>Security Tools Update Pipeline</span>
              </h2>
              <button
                onClick={() => setShowUpdateModal(false)}
                className="text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors p-1 rounded-lg hover:bg-[var(--bg-card)]"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="p-4 bg-[var(--bg-surface)]/80 flex-1 overflow-y-auto font-mono text-xs space-y-1 scrollbar-thin">
              {updateLogs.length === 0 && <div className="text-[var(--text-muted)]">Initializing update orchestration...</div>}
              {updateLogs.map((log, idx) => (
               <div key={idx} className="text-[var(--text-secondary)] break-words leading-relaxed">{log}</div>
              ))}
            </div>

            <div className="p-4 border-t border-[var(--border-card)] bg-[var(--bg-surface)] flex justify-end">
              <button
                onClick={() => setShowUpdateModal(false)}
                className="px-5 py-2 bg-[var(--bg-card)] hover:bg-[var(--border-card)] text-[var(--text-primary)] border border-[var(--border-card)] text-xs font-semibold rounded-xl transition-all shadow-sm"
              >
                {isUpdating ? 'Background Task' : 'Close'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Dependency Tools Modal */}
      {showDependencyModal && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-[var(--bg-card)] rounded-2xl border border-[var(--border-card)] shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[80vh]">
            <div className="p-4 border-b border-[var(--border-card)] flex items-center justify-between bg-[var(--bg-surface)]">
              <h2 className="text-sm font-bold text-[var(--text-primary)] flex items-center space-x-2">
                <ShieldAlert className="w-4 h-4 text-amber-500" />
                <span>Security Engine Dependencies</span>
              </h2>
              {(!isInstallingDependencies) && (
                <button
                  onClick={() => setShowDependencyModal(false)}
                  className="text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors p-1 rounded-lg hover:bg-[var(--bg-card)]"
                >
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <div className="p-6 bg-[var(--bg-surface)]/80 flex-1 overflow-y-auto space-y-4">
              <p className="text-xs text-[var(--text-secondary)]">
                The following security tools can be automatically managed or updated:
              </p>

              <div className="space-y-2">
                {dependencies.map((dep, idx) => (
                  <div key={idx} className="flex items-center justify-between p-3 rounded-xl bg-[var(--bg-card)] border border-[var(--border-card)]">
                    <span className="text-xs font-mono font-bold text-[var(--text-primary)] uppercase">{dep.name}</span>
                    <span className={`text-[11px] font-mono px-2 py-0.5 rounded-full ${dep.isInstalled ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/30' : 'bg-amber-500/10 text-amber-400 border border-amber-500/30'}`}>
                      {dep.isInstalled ? 'Installed' : dep.requiresManual ? 'Manual Install' : 'Auto-Install Available'}
                    </span>
                  </div>
                ))}
              </div>

              {dependencyLogs.length > 0 && (
                <div className="p-3 bg-black/40 rounded-xl font-mono text-[11px] text-[var(--text-muted)] space-y-1 max-h-36 overflow-y-auto">
                  {dependencyLogs.map((log, i) => (
                    <div key={i}>{log}</div>
                  ))}
                </div>
              )}
            </div>

            <div className="p-4 border-t border-[var(--border-card)] bg-[var(--bg-surface)] flex justify-end gap-3">
              <button
                onClick={() => setShowDependencyModal(false)}
                disabled={isInstallingDependencies}
                className="px-4 py-2 bg-[var(--bg-card)] hover:bg-[var(--border-card)] text-[var(--text-secondary)] text-xs font-semibold rounded-xl transition-all"
              >
                Later
              </button>
              <button
                onClick={handleInstallDependencies}
                disabled={isInstallingDependencies}
                className="px-5 py-2 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white text-xs font-bold rounded-xl transition-all shadow-md shadow-emerald-900/30 flex items-center space-x-2"
              >
                {isInstallingDependencies && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
                <span>{isInstallingDependencies ? 'Installing...' : 'Install Missing Engines'}</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import type { Vulnerability } from './vulnerability';

export interface ToolHealthInfo {
  name: string;
  displayName: string;
  category: 'recon' | 'dast' | 'fuzz' | 'network';
  installed: boolean;
  currentVersion: string;
  latestVersion: string;
  updateAvailable: boolean;
  resolvedPath: string;
  requiresManual?: boolean;
}

export {};

declare global {
  interface Window {
    api: {
      startScan: (targetUrl: string, config: Record<string, unknown>) => Promise<{success?: boolean; scanId?: string; error?: string}>;
      stopScan: (scanId: string) => Promise<{success?: boolean}>;
      onScanOutput: (callback: (event: unknown, data: { scanId: string, scanner: string, type: 'stdout' | 'stderr', message: string }) => void) => () => void;
      onScanStatus: (callback: (event: unknown, data: { scanId: string, status: string, scanner: string }) => void) => () => void;
      onScanFindings: (callback: (event: unknown, data: { scanId: string, scanner: string, findings: Vulnerability[] }) => void) => () => void;
      onScanStats: (callback: (event: unknown, data: { scanId: string, stats: any }) => void) => () => void;
      getHistory: () => Promise<any>;
      getFindingsPaginated: (scanId: string, options: { page?: number, limit?: number, severity?: string, scanner?: string, search?: string }) => Promise<{ findings: Vulnerability[], total: number, page: number, limit: number }>;
      openReportFolder: (scanId: string) => Promise<unknown>;
      exportReport: (scanId: string, format: 'html' | 'md' | 'json') => Promise<{ success: boolean; filePath: string }>;
      getReportStats: (scanId: string) => Promise<any>;
      getSettings: () => Promise<any>;
      saveSettings: (settings: any) => Promise<any>;
      analyzeLogs: (logs: string, prompt: string) => Promise<string>;
      onAiProgress: (callback: (event: unknown, msg: string) => void) => () => void;

      // Tool Manager & Health Matrix
      getToolsHealth: () => Promise<ToolHealthInfo[]>;
      updateTool: (toolName: string) => Promise<boolean>;
      updateAllTools: () => Promise<void>;
      onToolUpdateProgress: (callback: (event: unknown, data: { tool: string, message: string }) => void) => () => void;
      onToolUpdateStatus: (callback: (event: unknown, status: string) => void) => () => void;

      // Legacy updater
      updateTools: () => Promise<void>;
      onUpdateOutput: (callback: (event: unknown, msg: string) => void) => () => void;
      onUpdateStatus: (callback: (event: unknown, status: string) => void) => () => void;
      checkDependencies: () => Promise<any[]>;
      installDependencies: () => Promise<void>;
      onInstallProgress: (callback: (event: unknown, msg: string) => void) => () => void;
      openExternal: (url: string) => Promise<void>;
    }
  }
}
